// printSavingsSummary displays the savings total and enrolled offers count.
func printSavingsSummary(w io.Writer, data []byte) error {
	resp, err := parseAmexOffersResponse(data)
	if err != nil {
		return fmt.Errorf("parsing savings response: %w", err)
	}

	savings := resp.OffersSavings.Subtitle
	if savings == "" {
		savings = "$0.00"
	}
	enrolledCount := len(resp.AddedToCard.OffersList.Page1)

	fmt.Fprintf(w, "Saved via enrolled card offers: %s\n", savings)
	if enrolledCount > 0 {
		fmt.Fprintf(w, "%d active enrolled offer(s)\n", enrolledCount)
	} else {
		fmt.Fprintln(w, "No currently enrolled offers.")
	}
	return nil
}
